-- Payroll: 賞与 (docs/design/22-payroll.md §10).
-- Generated by `prisma migrate diff --from-schema-datamodel <previous schema> --to-schema-datamodel
-- prisma/schema.prisma --script`, then extended by hand (Prisma leaves CHECK constraints, functions
-- and triggers alone when it diffs the schema): CHECK constraints on payroll_bonus_run, and
-- payroll_bonus_run made append-only like payroll_run (02 §1).

-- CreateTable
CREATE TABLE "payroll_bonus_run" (
    "id" TEXT NOT NULL,
    "pay_month" TEXT NOT NULL,
    "payment_date" DATE NOT NULL,
    "title" TEXT NOT NULL,
    "calc_period_over_6_months" BOOLEAN NOT NULL,
    "pay_from_wallet_id" TEXT,
    "withholding_special_due" BOOLEAN NOT NULL,
    "table_ids" JSONB NOT NULL,
    "items" JSONB NOT NULL,
    "pay_entry_id" TEXT NOT NULL,
    "employer_entry_id" TEXT,
    "confirmed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "confirmed_by" TEXT NOT NULL,

    CONSTRAINT "payroll_bonus_run_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "payroll_bonus_run_pay_month_key" ON "payroll_bonus_run"("pay_month");

-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "payroll_bonus_run"
  ADD CONSTRAINT "payroll_bonus_run_pay_month_format"
    CHECK ("pay_month" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  -- 支給月 is the month of the payment date.
  ADD CONSTRAINT "payroll_bonus_run_pay_month_of_payment_date" CHECK (
    "pay_month" = lpad(extract(year FROM "payment_date")::int::text, 4, '0') || '-'
                  || lpad(extract(month FROM "payment_date")::int::text, 2, '0')
  ),
  ADD CONSTRAINT "payroll_bonus_run_title_not_blank" CHECK (btrim("title") <> ''),
  ADD CONSTRAINT "payroll_bonus_run_items_array" CHECK (jsonb_typeof("items") = 'array'),
  ADD CONSTRAINT "payroll_bonus_run_table_ids_object" CHECK (jsonb_typeof("table_ids") = 'object');

-- ---------------------------------------------------------------------------
-- payroll_bonus_run: append-only (UPDATE / DELETE / TRUNCATE rejected)
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_payroll_bonus_run_reject_change"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger guard: payroll_bonus_run is append-only (% of % rejected)', TG_OP, OLD."id";
END;
$$;

CREATE TRIGGER "payroll_bonus_run_reject_change"
  BEFORE UPDATE OR DELETE ON "payroll_bonus_run"
  FOR EACH ROW EXECUTE FUNCTION "ledger_payroll_bonus_run_reject_change"();

CREATE TRIGGER "payroll_bonus_run_reject_truncate"
  BEFORE TRUNCATE ON "payroll_bonus_run"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
